13	* { box-sizing: border-box; }
14	body {
15	    background: var(--paper); color: var(--ink);
16	    font-family: 'Helvetica Neue', Arial, 'PingFang TC', 'Microsoft JhengHei', 'Noto Sans TC', sans-serif;
17	    margin: 0; padding: 0 0 40px; display: flex; flex-direction: column; align-items: center;
18	}
19	.header-container { width: 100%; background: var(--ink); color: var(--white); text-align: center; padding: 48px 20px 40px; margin-bottom: 32px; }
20	h1 { color: var(--white); font-size: 48px; font-weight: 900; letter-spacing: 2px; margin: 0; }
21	p.subtitle { color: var(--line); font-size: 1rem; margin-top: 14px; }
22	p.subtitle-note { color: var(--line); font-size: .82rem; margin-top: 6px; opacity: .8; }
23	p.subtitle-warn { color: #FF6B6B; font-size: .88rem; font-weight: 700; margin-top: 10px; }
24	.nav-link { color: var(--gold); text-decoration: none; font-size: .85rem; font-weight: 700; letter-spacing: 1px; }
25	.nav-link:hover { color: var(--white); }
26	.footer-nav { width: 100%; max-width: 1200px; margin: 8px 20px 0; padding: 24px 20px; text-align: center; border-top: 1px solid var(--line); }
27	.footer-nav .nav-link:hover { color: var(--red-dark); }
28	
29	.tabs { display: flex; gap: 8px; flex-wrap: wrap; justify-content: center; width: 100%; max-width: 1200px; margin: 0 20px 24px; padding: 0 20px; }
30	.tab-btn {
31	    background: var(--white); border: 1px solid var(--line); color: var(--sub);
32	    padding: 11px 22px; border-radius: 4px; cursor: pointer; font-size: .9rem; font-weight: 700;
33	    letter-spacing: 1px; transition: all .15s ease;
34	}
35	.tab-btn.active { color: var(--white); background: var(--red); border-color: var(--red); }
36	.tab-btn:hover:not(.active) { border-color: var(--red); color: var(--red-dark); }
37	
38	.custom-months {
39	    display: flex; align-items: center; gap: 8px; justify-content: center; flex-wrap: wrap;
40	    width: 100%; max-width: 1200px; margin: 0 20px 28px; padding: 14px 20px;
41	    background: var(--white); border: 1px solid var(--line); border-radius: 4px; font-size: .9rem; color: var(--sub);
42	}
43	.custom-months input[type=number] {
44	    width: 80px; padding: 8px 10px; border: 1px solid var(--line); border-radius: 4px;
45	    font-size: .95rem; color: var(--ink); text-align: center;
46	}
47	.custom-months input[type=number]:focus { outline: none; border-color: var(--red); }
48	.custom-months button { padding: 8px 18px; font-size: .85rem; }
49	
50	.stats-row { display: flex; gap: 16px; flex-wrap: wrap; justify-content: center; width: 100%; max-width: 1200px; margin: 0 20px 28px; padding: 0 20px; }
51	.stat-card { background: var(--white); border: 1px solid var(--line); border-radius: 4px; padding: 18px 28px; text-align: center; min-width: 140px; }
52	.stat-card .num { font-size: 2rem; font-weight: 900; color: var(--red-dark); }
53	.stat-card .lbl { font-size: .85rem; color: var(--sub); margin-top: 4px; letter-spacing: 1px; }
54	
55	.section { width: 100%; max-width: 1200px; margin-bottom: 36px; padding: 0 20px; }
56	.section-title { color: var(--ink); font-size: 1.4rem; font-weight: 900; letter-spacing: 1px; text-align: center; margin: 0 0 6px 0; }
57	.section-sub { color: var(--sub); text-align: center; font-size: .86rem; margin: 0 0 24px 0; }
58	.section-title.warn { color: var(--red); }
59	
60	.table-wrapper { width: 100%; overflow-x: auto; background: var(--white); border: 1px solid var(--line); border-radius: 4px; }
61	table { width: 100%; border-collapse: collapse; font-size: .9rem; }
62	th { background: var(--ink); color: var(--white); padding: 12px 14px; text-align: left; font-weight: 700; letter-spacing: 1px; font-size: .85rem; }
63	td { padding: 10px 14px; border-bottom: 1px solid var(--line); color: var(--ink); }
64	tr.warn td { background: #FFF3F3; }
65	tr.warn td.months { color: var(--red); font-weight: 700; }
66	tr:last-child td { border-bottom: none; }
67	.empty { color: var(--sub); text-align: center; padding: 40px; font-size: .95rem; }
68	
69	.note-panel { width: 100%; max-width: 1200px; margin: 8px 20px 0; background: var(--white); border-radius: 4px; border: 1px solid var(--line); padding: 22px 28px; }
70	.note-panel p { color: var(--sub); line-height: 1.8; margin: 0; font-size: .86rem; }
71	
72	@media (max-width: 600px) {
73	    .header-container { padding: 36px 16px 30px; }
74	    h1 { font-size: 1.5rem; }
75	    .tabs, .stats-row, .section, .custom-months, .table-wrapper, .note-panel { padding-left: 12px; padding-right: 12px; margin-left: 0; margin-right: 0; }
76	}
