            <span class="aicon">⚠️</span>
            <span class="aname">${p.name}</span>
            <span class="achapter">${p.chapter || '-'}</span>
            ${lastHtml}
        </div>`;
    }).join('') + '</div>';
}

function renderDetail(filtered, query) {
    const q = (query || '').trim();
    const rows = filtered
        .filter(r => !q || r.name.includes(q))
        .sort((a, b) => b.event_date.localeCompare(a.event_date));
    const body = document.getElementById('detailBody');
    if (rows.length === 0) {
        body.innerHTML = '<tr><td colspan="4" style="text-align:center;color:#64748b;padding:24px;">沒有符合的紀錄</td></tr>';
        return;
    }
    body.innerHTML = rows.map(r => `
        <tr>
            <td class="td-date">${r.event_date}</td>
            <td class="td-name">${r.name}</td>
            <td class="td-chapter">${r.chapter || '-'}</td>
            <td class="td-type">${r.event_type}</td>
        </tr>
    `).join('');
}

let currentFiltered = [];

function renderAll(months) {
    currentFiltered = filterByWindow(months);
    renderStats(currentFiltered);
    renderRanking(currentFiltered);
    renderChapterRank(currentFiltered);
    renderAbsentees(currentFiltered, months);
    renderDetail(currentFiltered, document.getElementById('searchBox').value);
}

function clearActiveTabs() {
    document.querySelectorAll('#tabs .tab-btn').forEach(b => b.classList.remove('active'));
    document.getElementById('customMonthsResult').textContent = '';
}

document.querySelectorAll('#tabs .tab-btn').forEach(btn => {
    btn.addEventListener('click', () => {
        clearActiveTabs();
        btn.classList.add('active');
        renderAll(btn.dataset.months);
    });
});

function runCustomMonths() {
    const val = parseInt(document.getElementById('customMonths').value, 10);
    if (!val || val < 1) return;
    clearActiveTabs();
    document.getElementById('customMonthsResult').textContent = `目前顯示：近 ${val} 個月`;
    renderAll(String(val));
}
document.getElementById('customMonthsBtn').addEventListener('click', runCustomMonths);
document.getElementById('customMonths').addEventListener('keydown', (e) => {
    if (e.key === 'Enter') runCustomMonths();
});

document.getElementById('searchBox').addEventListener('input', (e) => {
    renderDetail(currentFiltered, e.target.value);
});

