136	    </div>
137	
138	    <script>
139	        const GROUPS = __GROUPS_JSON__;
140	        const STATS = __STATS_JSON__;
141	
142	        // 計算「距今幾個月」
143	        function monthsSince(visit_date) {
144	            const visit = new Date(visit_date);
145	            const now = new Date();
146	            const yearsDiff = now.getFullYear() - visit.getFullYear();
147	            const monthsDiff = now.getMonth() - visit.getMonth();
148	            let totalMonths = yearsDiff * 12 + monthsDiff;
149	            if (now.getDate() < visit.getDate()) totalMonths -= 1;
150	            return Math.max(0, totalMonths);
151	        }
152	
153	        // 預先算好每個組合的「距今月數」，存進 record
154	        const ENRICHED = GROUPS.map(g => ({
155	            ...g,
156	            months_ago: monthsSince(g.visit_date)
157	        }));
158	
159	        // 過�：months_ago >= N
160	        function filterByWindow(months) {
161	            const n = parseInt(months, 10);
162	            return ENRICHED.filter(r => r.months_ago >= n);
163	        }
164	
165	        // 排序：距今月數由大到小（最久沒邀約在最上面），同月數比照培訓總覽排行榜慣例按姓名排序
166	        function renderList(filtered) {
167	            const sorted = filtered.slice().sort((a, b) => b.months_ago - a.months_ago || a.inviter.localeCompare(b.inviter));
168	            const tbody = document.getElementById('rankTableBody');
169	            if (sorted.length === 0) {
170	                tbody.innerHTML = '<tr><td colspan="5" class="empty">這個門�下沒有會員（每位會員最近都有邀約來賓）</td></tr>';
171	                return;
172	            }
173	            const html = sorted.map((r, i) => {
174	                const isWarn = r.months_ago >= 12;
175	                const cls = isWarn ? 'warn' : '';
176	                return `<tr class="${cls}">
177	                    <td>${i + 1}</td>
178	                    <td>${r.inviter}</td>
179	                    <td>${r.chapter}</td>
180	                    <td>${r.visit_date}</td>
181	                    <td class="months">${r.months_ago} 個月</td>
182	                </tr>`;
183	            }).join('');
184	            tbody.innerHTML = html;
185	        }
186	
187	        function renderStats(filtered) {
188	            const el = document.getElementById('statsRow');
189	            el.innerHTML = `
190	                <div class="stat-card"><div class="num">${filtered.length}</div><div class="lbl">超過門檻人數</div></div>
191	                <div class="stat-card"><div class="num">${STATS.total_groups}</div><div class="lbl">(邀請人, 分會) 組合</div></div>
192	                <div class="stat-card"><div class="num">${STATS.unique_inviters}</div><div class="lbl">獨立邀請人數</div></div>
193	                <div class="stat-card"><div class="num">${STATS.chapters.length}</div><div class="lbl">涵蓋分會數</div></div>
194	            `;
195	        }
196	
197	        function renderSub(filtered, months) {
198	            const sub = document.getElementById('rankSub');
199	            sub.innerHTML = `最近一次邀約已超過 ${months} 個月｜共 ${filtered.length} 個 (邀請人, 分會) 組合`;
200	        }
201	
202	        let currentMonths = 6;
203	        function apply(months) {
204	            currentMonths = months;
205	            const filtered = filterByWindow(months);
206	            renderStats(filtered);
207	            renderSub(filtered, months);
208	            renderList(filtered);
209	            // 更新 tab 樣式
210	            document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
211	            document.querySelector(`.tab-btn[data-months="${months}"]`)?.classList.add('active');
212	        }
213	
214	        // tab 按鈕
215	        document.querySelectorAll('#tabs .tab-btn').forEach(btn => {
216	            btn.addEventListener('click', () => {
217	                apply(parseInt(btn.dataset.months, 10));
218	            });
219	        });
220	
221	        // 自訂輸入框
222	        document.getElementById('customMonthsBtn').addEventListener('click', () => {
223	            const v = parseInt(document.getElementById('customMonths').value, 10);
224	            if (!v || v < 1) {
225	                alert('請輸入正整數月數');
226	                return;
227	            }
228	            apply(v);
229	        });
230	
231	        // 初始 render
232	        apply(6);
233	    </script>
234	</body>
235	</html>
